// Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
}

public boolean hasPathSum(TreeNode root, int targetSum) {
    if (root == null) return false;                       // no path here
    int remaining = targetSum - root.val;
    if (root.left == null && root.right == null) {        // leaf: the only place to decide
        return remaining == 0;
    }
    return hasPathSum(root.left, remaining)
        || hasPathSum(root.right, remaining);             // one good path is enough
}

public boolean hasPathSum(TreeNode root, int targetSum) {
    if (root == null) return false;
    Deque<TreeNode> nodes = new ArrayDeque<>();
    Deque<Integer> remaining = new ArrayDeque<>();
    nodes.push(root);
    remaining.push(targetSum - root.val);
    while (!nodes.isEmpty()) {
        TreeNode node = nodes.pop();
        int rem = remaining.pop();
        if (node.left == null && node.right == null && rem == 0) {
            return true;                                  // leaf landed exactly
        }
        if (node.left != null) {
            nodes.push(node.left);
            remaining.push(rem - node.left.val);
        }
        if (node.right != null) {
            nodes.push(node.right);
            remaining.push(rem - node.right.val);
        }
    }
    return false;
}

